class StringIterator:
    def __init__(self, s: str):
        self.tokens = []
        i = 0
        while i < len(s):
            c = s[i]; i += 1
            j = i
            while i < len(s) and s[i].isdigit(): i += 1
            self.tokens.append([c, int(s[j:i])])
        self.idx = 0
    def next(self) -> str:
        if not self.hasNext(): return ' '
        self.tokens[self.idx][1] -= 1
        res = self.tokens[self.idx][0]
        if self.tokens[self.idx][1] == 0: self.idx += 1
        return res
    def hasNext(self) -> bool:
        return self.idx < len(self.tokens)

class Solution:
    def canPlaceFlowers(self, flowerbed: List[int], n: int) -> bool:
        count = 0
        for i in range(len(flowerbed)):
            if flowerbed[i] == 0 and (i == 0 or flowerbed[i-1] == 0) and (i == len(flowerbed)-1 or flowerbed[i+1] == 0):
                flowerbed[i] = 1
                count += 1
        return count >= n

class Solution:
    def tree2str(self, root: Optional[TreeNode]) -> str:
        if not root: return ''
        s = str(root.val)
        if root.left or root.right:
            s += '(' + self.tree2str(root.left) + ')'
        if root.right:
            s += '(' + self.tree2str(root.right) + ')'
        return s

class Solution:
    def findDuplicate(self, paths: List[str]) -> List[List[str]]:
        from collections import defaultdict
        d = defaultdict(list)
        for p in paths:
            parts = p.split()
            root = parts[0]
            for f in parts[1:]:
                name, content = f.split('(')
                d[content[:-1]].append(root+'/'+name)
        return [v for v in d.values() if len(v) > 1]

class Solution:
    def triangleNumber(self, nums: List[int]) -> int:
        nums.sort()
        count = 0
        for k in range(2, len(nums)):
            i, j = 0, k-1
            while i < j:
                if nums[i]+nums[j] > nums[k]:
                    count += j-i
                    j -= 1
                else:
                    i += 1
        return count

class Solution:
    def addBoldTag(self, s: str, words: List[str]) -> str:
        bold = [False]*len(s)
        for w in words:
            start = s.find(w)
            while start != -1:
                for i in range(start, start+len(w)): bold[i] = True
                start = s.find(w, start+1)
        res, i = [], 0
        while i < len(s):
            if bold[i]:
                res.append('<b>')
                while i < len(s) and bold[i]: res.append(s[i]); i += 1
                res.append('</b>')
            else: res.append(s[i]); i += 1
        return ''.join(res)

class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        from collections import Counter
        freq = list(Counter(tasks).values())
