class MyCircularQueue:
    def __init__(self, k: int):
        self.q = [0]*k
        self.head = self.count = 0
        self.size = k
    def enQueue(self, value: int) -> bool:
        if self.isFull(): return False
        self.q[(self.head+self.count)%self.size] = value
        self.count += 1
        return True
    def deQueue(self) -> bool:
        if self.isEmpty(): return False
        self.head = (self.head+1)%self.size
        self.count -= 1
        return True
    def Front(self) -> int:
        return -1 if self.isEmpty() else self.q[self.head]
    def Rear(self) -> int:
        return -1 if self.isEmpty() else self.q[(self.head+self.count-1)%self.size]
    def isEmpty(self) -> bool:
        return self.count == 0
    def isFull(self) -> bool:
        return self.count == self.size

class Solution:
    def addOneRow(self, root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
        if depth == 1:
            node = TreeNode(val); node.left = root; return node
        queue = [root]
        for _ in range(depth-2):
            queue = [c for n in queue for c in (n.left, n.right) if c]
        for n in queue:
            l, r = n.left, n.right
            n.left, n.right = TreeNode(val), TreeNode(val)
            n.left.left, n.right.right = l, r
        return root

class Solution:
    def maxDistance(self, arrays: List[List[int]]) -> int:
        mn, mx = arrays[0][0], arrays[0][-1]
        res = 0
        for i in range(1, len(arrays)):
            res = max(res, abs(arrays[i][-1]-mn), abs(mx-arrays[i][0]))
            mn = min(mn, arrays[i][0])
            mx = max(mx, arrays[i][-1])
