class Solution:
    def smallestFactorization(self, a: int) -> int:
        if a < 10: return a
        digits = []
        for d in range(9, 1, -1):
            while a % d == 0:
                digits.append(d); a //= d
        if a > 1: return 0
        res = int(''.join(map(str, reversed(digits))))
        return res if res <= 2**31-1 else 0

