class Solution:
    def kInversePairs(self, n: int, k: int) -> int:
        MOD = 10**9+7
        dp = [[0]*(k+1) for _ in range(n+1)]
        dp[0][0] = 1
        for i in range(1, n+1):
            dp[i][0] = 1
            for j in range(1, k+1):
                dp[i][j] = (dp[i][j-1]+dp[i-1][j])%MOD
                if j >= i: dp[i][j] = (dp[i][j]-dp[i-1][j-i])%MOD
        return dp[n][k]%MOD

class Solution:
    def scheduleCourse(self, courses: List[List[int]]) -> int:
        import heapq
        courses.sort(key=lambda x: x[1])
        heap, time = [], 0
        for dur, end in courses:
            time += dur
            heapq.heappush(heap, -dur)
            if time > end: time += heapq.heappop(heap)
        return len(heap)

class Excel:
    def __init__(self, height: int, width: str):
        self.h = height
        self.mat = [[0]*(ord(width)-64+1) for _ in range(height+1)]
        self.form = {}
    def set(self, row: int, column: str, val: int) -> None:
        self.form.pop((row,column), None)
        self.mat[row][ord(column)-64] = val
    def get(self, row: int, column: str) -> int:
        if (row,column) in self.form:
            return self._calc(self.form[(row,column)])
        return self.mat[row][ord(column)-64]
    def sum(self, row: int, column: str, numbers: List[str]) -> int:
        self.form[(row,column)] = numbers
        v = self._calc(numbers)
        self.mat[row][ord(column)-64] = v
        return v
    def _calc(self, nums):
        t = 0
        for s in nums:
            if ':' in s:
                p = s.split(':')
                c1,r1,c2,r2 = p[0][0],int(p[0][1:]),p[1][0],int(p[1][1:])
                for r in range(r1,r2+1):
                    for c in range(ord(c1),ord(c2)+1): t += self.get(r,chr(c))
            else: t += self.get(int(s[1:]),s[0])
        return t

