class Solution:
    def exclusiveTime(self, n: int, logs: List[str]) -> List[int]:
        res = [0]*n
        stack = []
        for log in logs:
            parts = log.split(':')
            fid, typ, ts = int(parts[0]), parts[1], int(parts[2])
            if typ == 'start':
                stack.append([fid, ts])
            else:
                _, start = stack.pop()
                dur = ts - start + 1
                res[fid] += dur
                if stack: res[stack[-1][0]] -= dur
        return res

class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> List[float]:
        from collections import deque
        res, q = [], deque([root])
        while q:
            s, n = 0, len(q)
            for _ in range(n):
                node = q.popleft()
                s += node.val
                if node.left: q.append(node.left)
                if node.right: q.append(node.right)
            res.append(s/n)
        return res

class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def dfs(needs):
            res = sum(needs[i]*price[i] for i in range(len(price)))
            for sp in special:
                nn = tuple(needs[i]-sp[i] for i in range(len(price)))
                if all(x >= 0 for x in nn):
                    res = min(res, sp[-1]+dfs(nn))
            return res
        return dfs(tuple(needs))

class Solution:
    def solveEquation(self, equation: str) -> str:
        import re
        def parse(s):
            coef = const = 0
            for m in re.finditer(r'[+-]?[^+-]+', s):
                t = m.group()
                if 'x' in t:
                    t = t.replace('x','')
                    coef += int(t) if t not in ('','+','-') else (1 if t != '-' else -1)
                else:
                    const += int(t)
            return coef, const
        left, right = equation.split('=')
        lc, ln = parse(left)
        rc, rn = parse(right)
        coef, num = lc-rc, rn-ln
        if coef == 0: return 'Infinite solutions' if num == 0 else 'No solution'
        return f'x={num//coef}'

class AutocompleteSystem:
    def __init__(self, sentences, times):
        self.freq = {}
        for s, t in zip(sentences, times): self.freq[s] = self.freq.get(s,0)+t
        self.cur = ''
    def input(self, c: str):
        if c == '#':
            self.freq[self.cur] = self.freq.get(self.cur,0)+1
            self.cur = ''
            return []
        self.cur += c
        cands = [(s,f) for s,f in self.freq.items() if s.startswith(self.cur)]
        cands.sort(key=lambda x: (-x[1], x[0]))
        return [s for s,_ in cands[:3]]

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        s = sum(nums[:k])
        mx = s
        for i in range(k, len(nums)):
            s += nums[i] - nums[i-k]
            mx = max(mx, s)
        return mx / k

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        lo, hi = min(nums), max(nums)
        while hi - lo > 1e-5:
            mid = (lo+hi)/2
            s = mn = 0
            prev = 0
            found = False
            for i in range(len(nums)):
                s += nums[i] - mid
                if i >= k-1:
                    if i >= k: prev += nums[i-k]-mid; mn = min(mn, prev)
                    if s - mn >= 0: found = True; break
            if found: lo = mid
            else: hi = mid
        return lo

class Solution:
    def findErrorNums(self, nums: List[int]) -> List[int]:
        from collections import Counter
        c = Counter(nums)
        dup = miss = 0
        for i in range(1, len(nums)+1):
            if c[i] == 2: dup = i
            if c[i] == 0: miss = i
