class Solution:
    def findLongestChain(self, pairs: List[List[int]]) -> int:
        pairs.sort(key=lambda x: x[1])
        cur, count = float('-inf'), 0
        for a, b in pairs:
            if a > cur:
                count += 1
                cur = b
        return count

class Solution:
    def countSubstrings(self, s: str) -> int:
        count = 0
        for i in range(len(s)):
            for l, r in [(i,i),(i,i+1)]:
                while l >= 0 and r < len(s) and s[l]==s[r]:
                    count += 1; l -= 1; r += 1
        return count

class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        roots = set(dictionary)
        words = sentence.split()
        for i, w in enumerate(words):
            for j in range(1, len(w)+1):
                if w[:j] in roots:
                    words[i] = w[:j]; break
        return ' '.join(words)

class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        from collections import deque
        r, d = deque(), deque()
        n = len(senate)
        for i, c in enumerate(senate):
            if c == 'R': r.append(i)
            else: d.append(i)
        while r and d:
            ri, di = r.popleft(), d.popleft()
            if ri < di: r.append(ri+n)
            else: d.append(di+n)
        return 'Radiant' if r else 'Dire'

class Solution:
    def minSteps(self, n: int) -> int:
        res, d = 0, 2
        while n > 1:
            while n % d == 0:
                res += d
                n //= d
            d += 1
        return res

class Solution:
    def maxA(self, n: int) -> int:
        dp = list(range(n+1))
        for i in range(1, n+1):
            for j in range(i-3, -1, -1):
                dp[i] = max(dp[i], dp[j]*(i-j-1))
        return dp[n]

class Solution:
    def findDuplicateSubtrees(self, root: Optional[TreeNode]) -> List[Optional[TreeNode]]:
        from collections import defaultdict
        count = defaultdict(int)
        res = []
        def serialize(node):
            if not node: return '#'
            s = f'{node.val},{serialize(node.left)},{serialize(node.right)}'
            count[s] += 1
            if count[s] == 2: res.append(node)
            return s
        serialize(root)
        return res

class Solution:
    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
        seen = set()
        def dfs(node):
            if not node: return False
            if k-node.val in seen: return True
            seen.add(node.val)
            return dfs(node.left) or dfs(node.right)
        return dfs(root)

class Solution:
    def printTree(self, root: Optional[TreeNode]) -> List[List[str]]:
        def height(node):
            if not node: return 0
            return 1 + max(height(node.left), height(node.right))
        h = height(root)
        w = 2**h - 1
        res = [['']*w for _ in range(h)]
        def fill(node, r, l, ri):
            if not node: return
            mid = (l+ri)//2
            res[r][mid] = str(node.val)
            fill(node.left, r+1, l, mid-1)
            fill(node.right, r+1, mid+1, ri)
        fill(root, 0, 0, w-1)
        return res

