class Solution:
    def findClosestElements(self, arr: List[int], k: int, x: int) -> List[int]:
        lo, hi = 0, len(arr)-k
        while lo < hi:
            mid = (lo+hi)//2
            if x-arr[mid] > arr[mid+k]-x: lo = mid+1
            else: hi = mid
        return arr[lo:lo+k]

class Solution:
    def newInteger(self, n: int) -> int:
        res = ''
        while n:
            res = str(n%9) + res
            n //= 9
        return int(res)
